
'{"questions":[{"id":"q1","question":"Do you already have an open family law case?","options":[{"label":"Yes, I have an existing case","value":"yes_case","next":"q2"},{"label":"No, I need to start a new case","value":"no_case","next":"q3"},{"label":"I am not sure","value":"unsure_case","next":"q3"}]},{"id":"q2","question":"What do you need to do?","options":[{"label":"Request new or changed custody/visitation orders","value":"request","next":"q4"},{"label":"Respond to a request the other parent filed","value":"respond","result_key":"response_track"},{"label":"Enforce an existing order","value":"enforce","result_key":"enforcement_track"},{"label":"I need emergency orders right away","value":"emergency","result_key":"emergency_track"}]},{"id":"q3","question":"Is there an immediate safety concern for you or your children?","options":[{"label":"Yes, I need emergency protection","value":"emergency","result_key":"emergency_track"},{"label":"No, but I want to establish custody","value":"no_emergency","next":"q4"}]},{"id":"q4","question":"Can you and the other parent agree on a plan?","options":[{"label":"Yes, we can agree","value":"agree","result_key":"agreement_track"},{"label":"No, we cannot agree","value":"disagree","result_key":"contested_track"},{"label":"I need supervised visitation","value":"supervised","result_key":"supervised_track"}]}],"results":[{"key":"agreement_track","title":"Agreement Track","description":"Since you and the other parent can agree, you can create a parenting plan together and submit it to the court. This is usually the fastest path.","track":"Agreement / Stipulation","recommended_forms":["FL-300 — Request for Order","FL-311 — Custody/Visitation Application","FL-341 — Custody/Visitation Order Attachment","FL-341(C) — Holiday Schedule"],"checklist":["Draft a parenting plan together","Complete FL-300 and FL-311","File with the court clerk","Attend any required mediation","Get the judge to sign your agreement (FL-341)"]},{"key":"contested_track","title":"Contested Track","description":"When parents cannot agree, you will need to file a Request for Order, attend mediation, and prepare for a court hearing.","track":"Contested / Hearing Required","recommended_forms":["FL-300 — Request for Order","FL-311 — Custody/Visitation Application","FL-300-INFO — Information Sheet"],"checklist":["Complete FL-300 and FL-311","File with the court and pay filing fee (or request fee waiver)","Serve the other parent at least 16 court days before the hearing","Attend Family Court Services mediation","Prepare evidence for your hearing","Attend the hearing"]},{"key":"response_track","title":"Response Track","description":"The other parent has filed a Request for Order. You need to file a Responsive Declaration and attend the hearing.","track":"Responding to a Request","recommended_forms":["FL-320 — Responsive Declaration to Request for Order","FL-311 — Custody/Visitation Application (if requesting different orders)"],"checklist":["Read the papers you were served carefully","Complete FL-320 with your response","File FL-320 with the court and serve on the other parent","Attend mediation if required","Attend the hearing on the scheduled date"]},{"key":"emergency_track","title":"Emergency / Safety Track","description":"If there is an immediate safety concern, you may be able to get temporary emergency orders without the normal waiting period.","track":"Emergency (Ex Parte)","is_emergency":true,"recommended_forms":["FL-305 — Temporary Emergency (Ex Parte) Orders","FL-300 — Request for Order","FL-311 — Custody/Visitation Application"],"checklist":["If in immediate danger, call 911","Contact the National DV Hotline: 1-800-799-7233","Complete FL-305 (Ex Parte) and FL-300","File with the court — ask the clerk for an emergency hearing","Notify the other parent (or explain why you cannot)","Attend the emergency hearing"]},{"key":"enforcement_track","title":"Enforcement Track","description":"If the other parent is not following the court order, you can ask the court to enforce it.","track":"Order Enforcement","recommended_forms":["FL-300 — Request for Order","FL-311 — Custody/Visitation Application"],"checklist":["Document each violation (dates, details)","Complete FL-300 describing the violations","File with the court and serve the other parent","Attend the hearing with evidence of violations"]},{"key":"supervised_track","title":"Supervised Visitation Track","description":"If you believe supervised visitation is necessary for the child''s safety, you can request it through the court.","track":"Supervised Visitation","recommended_forms":["FL-300 — Request for Order","FL-311 — Custody/Visitation Application","FL-341(A) — Supervised Visitation and Exchanges Order"],"checklist":["Complete FL-300 requesting supervised visitation","Explain your reasons clearly in FL-311","File with the court","Research supervised visitation providers in your county","Attend mediation and the hearing"]}]}'::jsonb);
